<script setup>import AppShell from'../Layouts/AppShell.vue';import StateCard from'../Components/StateCard.vue';import{Head,useForm}from'@inertiajs/vue3';defineProps({subject:Object,photos:Array,event:Object});const action=useForm({});</script><template><AppShell><Head title="My Photos"/><div class="mx-auto max-w-6xl"><p class="eyebrow">Private discovery</p><h1 class="mt-2 font-display text-3xl font-bold">My Photos · {{event.name}}</h1><p class="mt-3 text-sm text-black/50">Results are filtered again against your current event and gallery permissions.</p><StateCard v-if="subject.state!=='completed'" class="mt-8" :title="subject.state==='failed'?'We could not complete your search':'Finding your moments'" :message="subject.state==='failed'?'Your selfie was deleted. You can retry safely.':'Your private search is processing in the background.'" :tone="subject.state==='failed'?'error':'neutral'"/><StateCard v-else-if="!photos.length" class="mt-8" title="No matches yet" message="We did not find an above-threshold match in the photographs you can access."/><div v-else class="photo-grid mt-8 grid grid-cols-2 gap-1 md:grid-cols-3 lg:grid-cols-4"><figure v-for="p in photos" :key="p.match_id" class="group relative aspect-[4/3] overflow-hidden bg-black/10"><img :src="p.url" class="h-full w-full object-cover"><button class="absolute bottom-2 right-2 bg-black/70 px-3 py-2 text-xs font-semibold text-white" @click="action.post(`/face-matches/${p.match_id}/reject`)">This is not me</button></figure></div></div></AppShell></template>
